// Generates testdata/baseline-b-attributes.txt: the DER of every signed attribute
// CAdESLevelBaselineB#getSignedAttributes produces, for a fixed set of signature parameters.
// The Go port's cades.CAdESLevelBaselineB must reproduce these bytes exactly - that is the
// point of the CAdES-B chunk, so the expectations are upstream DSS's own output rather than
// anything derived by hand.
//
// Run it with OpenJDK 21 against the built upstream DSS 6.5.RC1 and its dependencies:
//
//   cd /home/user/dss-upstream
//   mvn -o -pl dss-cades dependency:build-classpath -Dmdep.outputFile=/tmp/cades_cp.txt
//   CP="dss-cades/target/classes:dss-cms-object/target/classes:$(cat /tmp/cades_cp.txt)"
//   javac -cp "$CP" -d /tmp/cadesfix BaselineBFixtures.java
//   java  -cp "$CP:/tmp/cadesfix" BaselineBFixtures <testdata directory>
//
// Inputs are the checked-in testdata/signer.crt (the "Plain Signer" test certificate, taken
// verbatim from spi/validation/testdata/plain.crt) and testdata/content-timestamp.tst (the RFC
// 3161 token of spi/validation/testdata/timestamp-token.tst). Every date is fixed, and every
// content-identifier suffix is supplied explicitly, so a re-run reproduces the same bytes.
import eu.europa.esig.dss.cades.CAdESSignatureParameters;
import eu.europa.esig.dss.cades.signature.CAdESLevelBaselineB;
import eu.europa.esig.dss.enumerations.CommitmentTypeEnum;
import eu.europa.esig.dss.enumerations.DigestAlgorithm;
import eu.europa.esig.dss.enumerations.MimeTypeEnum;
import eu.europa.esig.dss.enumerations.ObjectIdentifierQualifier;
import eu.europa.esig.dss.enumerations.SignatureLevel;
import eu.europa.esig.dss.enumerations.SignaturePackaging;
import eu.europa.esig.dss.enumerations.TimestampType;
import eu.europa.esig.dss.model.CommitmentQualifier;
import eu.europa.esig.dss.model.CommonCommitmentType;
import eu.europa.esig.dss.model.DSSDocument;
import eu.europa.esig.dss.model.InMemoryDocument;
import eu.europa.esig.dss.model.Policy;
import eu.europa.esig.dss.model.SignerLocation;
import eu.europa.esig.dss.model.SpDocSpecification;
import eu.europa.esig.dss.model.UserNotice;
import eu.europa.esig.dss.model.x509.CertificateToken;
import eu.europa.esig.dss.spi.x509.tsp.TimestampToken;
import org.bouncycastle.asn1.ASN1Encodable;
import org.bouncycastle.asn1.ASN1EncodableVector;
import org.bouncycastle.asn1.DERSet;
import org.bouncycastle.asn1.cms.Attribute;
import org.bouncycastle.asn1.cms.AttributeTable;

import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.security.cert.CertificateFactory;
import java.security.cert.X509Certificate;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Calendar;
import java.util.Collections;
import java.util.Date;
import java.util.List;
import java.util.TimeZone;

public class BaselineBFixtures {

    static Path testdata;
    static CertificateToken signer;
    static StringBuilder out = new StringBuilder();

    public static void main(String[] args) throws Exception {
        testdata = Paths.get(args[0]);
        signer = loadCertificate(testdata.resolve("signer.crt"));

        out.append("# CAdESLevelBaselineB#getSignedAttributes, DSS 6.5.RC1. Generated by gen/BaselineBFixtures.java.\n");
        out.append("# case <name> / attr <hex of the Attribute DER> ... / set <hex of the DER SET OF>\n");

        // ---------------------------------------------------------------- signing certificate
        emit("signing-certificate-sha256", base(DigestAlgorithm.SHA256, null));
        emit("signing-certificate-sha1", base(DigestAlgorithm.SHA1, null));
        emit("signing-certificate-sha512", base(DigestAlgorithm.SHA512, null));
        emit("signing-certificate-sha3-256", base(DigestAlgorithm.SHA3_256, null));

        // no signing certificate at all: TBS generated without one
        CAdESSignatureParameters noCert = empty();
        noCert.setGenerateTBSWithoutCertificate(true);
        noCert.bLevel().setSigningDate(date(2021, 1, 15, 10, 30, 45));
        emit("no-signing-certificate", noCert);

        // ---------------------------------------------------------------- signing time
        emit("signing-time-utc", base(DigestAlgorithm.SHA256, date(2021, 1, 15, 10, 30, 45)));
        emit("signing-time-1950", base(DigestAlgorithm.SHA256, date(1950, 1, 1, 0, 0, 0)));
        emit("signing-time-2049", base(DigestAlgorithm.SHA256, date(2049, 12, 31, 23, 59, 59)));
        // outside [1950, 2049]: org.bouncycastle.asn1.x509.Time switches to GeneralizedTime
        emit("signing-time-2050", base(DigestAlgorithm.SHA256, date(2050, 1, 1, 0, 0, 0)));
        emit("signing-time-1949", base(DigestAlgorithm.SHA256, date(1949, 12, 31, 23, 59, 59)));

        // ---------------------------------------------------------------- signer attributes
        CAdESSignatureParameters roles = base(DigestAlgorithm.SHA256, null);
        roles.bLevel().setClaimedSignerRoles(Arrays.asList("Manager", "Head of Unit"));
        emit("claimed-roles-en319122", roles);

        CAdESSignatureParameters rolesOld = base(DigestAlgorithm.SHA256, null);
        rolesOld.setEn319122(false);
        rolesOld.bLevel().setClaimedSignerRoles(Arrays.asList("Manager", "Head of Unit"));
        emit("claimed-roles-ts101733", rolesOld);

        CAdESSignatureParameters assertions = base(DigestAlgorithm.SHA256, null);
        assertions.bLevel().setSignedAssertions(Arrays.asList("assertion-one", "assertion-two"));
        emit("signed-assertions", assertions);

        // signedAssertions are ignored when the old format is requested
        CAdESSignatureParameters assertionsOld = base(DigestAlgorithm.SHA256, null);
        assertionsOld.setEn319122(false);
        assertionsOld.bLevel().setSignedAssertions(Collections.singletonList("assertion-one"));
        emit("signed-assertions-ts101733", assertionsOld);

        // claimed roles win over signed assertions
        CAdESSignatureParameters both = base(DigestAlgorithm.SHA256, null);
        both.bLevel().setClaimedSignerRoles(Collections.singletonList("Manager"));
        both.bLevel().setSignedAssertions(Collections.singletonList("assertion-one"));
        emit("claimed-roles-and-assertions", both);

        // ---------------------------------------------------------------- signature policy
        CAdESSignatureParameters implicitPolicy = base(DigestAlgorithm.SHA256, null);
        implicitPolicy.bLevel().setSignaturePolicy(new Policy());
        emit("policy-implicit", implicitPolicy);

        CAdESSignatureParameters explicitPolicy = base(DigestAlgorithm.SHA256, null);
        explicitPolicy.bLevel().setSignaturePolicy(policy(false, false, false));
        emit("policy-explicit", explicitPolicy);

        CAdESSignatureParameters policySpuri = base(DigestAlgorithm.SHA256, null);
        policySpuri.bLevel().setSignaturePolicy(policy(true, false, false));
        emit("policy-spuri", policySpuri);

        CAdESSignatureParameters policyNotice = base(DigestAlgorithm.SHA256, null);
        policyNotice.bLevel().setSignaturePolicy(policy(false, true, false));
        emit("policy-user-notice", policyNotice);

        CAdESSignatureParameters policyDocSpec = base(DigestAlgorithm.SHA256, null);
        policyDocSpec.bLevel().setSignaturePolicy(policy(false, false, true));
        emit("policy-doc-specification", policyDocSpec);

        CAdESSignatureParameters policyAll = base(DigestAlgorithm.SHA256, null);
        policyAll.bLevel().setSignaturePolicy(policy(true, true, true));
        emit("policy-all-qualifiers", policyAll);

        // a SpDocSpecification carrying a URI rather than an OID
        CAdESSignatureParameters policyDocSpecUri = base(DigestAlgorithm.SHA256, null);
        Policy uriDocSpec = policy(false, false, true);
        uriDocSpec.getSpDocSpecification().setId("http://spec.example.org/policy");
        policyDocSpecUri.bLevel().setSignaturePolicy(uriDocSpec);
        emit("policy-doc-specification-uri", policyDocSpecUri);

        // a UserNotice with only an explicit text, and one with only a notice reference
        CAdESSignatureParameters policyNoticeText = base(DigestAlgorithm.SHA256, null);
        Policy textOnly = policy(false, false, false);
        UserNotice explicitTextOnly = new UserNotice();
        explicitTextOnly.setExplicitText("Only an explicit text");
        textOnly.setUserNotice(explicitTextOnly);
        policyNoticeText.bLevel().setSignaturePolicy(textOnly);
        emit("policy-user-notice-text-only", policyNoticeText);

        // NOT EMITTED: a UserNotice carrying only a notice reference (organization + notice
        // numbers, no explicit text) passes DSSUtils#assertSPUserNoticeConfigurationValid and
        // then makes CAdESLevelBaselineB#buildSigPolicyQualifiers call
        // org.bouncycastle.asn1.x509.UserNotice(NoticeReference, (String) null), which hands the
        // null to DisplayText(String) and raises a NullPointerException. There is no ground
        // truth to capture; the Go port reports the same configuration as an error, see
        // cades_level_baseline_b_test.go.

        // ---------------------------------------------------------------- content hints
        CAdESSignatureParameters hints = base(DigestAlgorithm.SHA256, null);
        hints.setContentHintsType("1.2.840.113549.1.7.1");
        hints.setContentHintsDescription("text/plain");
        emit("content-hints", hints);

        CAdESSignatureParameters hintsNoDescription = base(DigestAlgorithm.SHA256, null);
        hintsNoDescription.setContentHintsType("1.2.840.113549.1.7.1");
        emit("content-hints-no-description", hintsNoDescription);

        // ---------------------------------------------------------------- content identifier
        CAdESSignatureParameters identifier = base(DigestAlgorithm.SHA256, null);
        identifier.setContentIdentifierPrefix("DSS-");
        identifier.setContentIdentifierSuffix("20210115103045Z-4242");
        emit("content-identifier", identifier);

        // ---------------------------------------------------------------- commitment type
        CAdESSignatureParameters commitment = base(DigestAlgorithm.SHA256, null);
        commitment.bLevel().setCommitmentTypeIndications(Arrays.asList(
                CommitmentTypeEnum.ProofOfOrigin, CommitmentTypeEnum.ProofOfReceipt));
        emit("commitment-type", commitment);

        CAdESSignatureParameters commitmentQualified = base(DigestAlgorithm.SHA256, null);
        CommonCommitmentType qualified = new CommonCommitmentType();
        qualified.setOid("1.2.840.113549.1.9.16.6.1");
        CommitmentQualifier asn1Qualifier = new CommitmentQualifier();
        asn1Qualifier.setOid("1.2.3.4.1");
        // a DER PrintableString "qualifier", so DSSASN1Utils#isAsn1Encoded takes the ASN.1 branch
        asn1Qualifier.setContent(new InMemoryDocument(new byte[] {
                0x13, 0x09, 'q', 'u', 'a', 'l', 'i', 'f', 'i', 'e', 'r' }));
        CommitmentQualifier textQualifier = new CommitmentQualifier();
        textQualifier.setOid("1.2.3.4.2");
        textQualifier.setContent(new InMemoryDocument("plain text qualifier".getBytes(StandardCharsets.UTF_8)));
        qualified.setCommitmentTypeQualifiers(asn1Qualifier, textQualifier);
        commitmentQualified.bLevel().setCommitmentTypeIndications(Collections.singletonList(qualified));
        emit("commitment-type-qualifiers", commitmentQualified);

        // ---------------------------------------------------------------- signer location
        CAdESSignatureParameters location = base(DigestAlgorithm.SHA256, null);
        SignerLocation signerLocation = new SignerLocation();
        signerLocation.setCountry("LU");
        signerLocation.setLocality("Luxembourg");
        signerLocation.setPostalAddress(Arrays.asList("Line 1", "Line 2", "Line 3"));
        location.bLevel().setSignerLocation(signerLocation);
        emit("signer-location", location);

        CAdESSignatureParameters locationCountryOnly = base(DigestAlgorithm.SHA256, null);
        SignerLocation countryOnly = new SignerLocation();
        countryOnly.setCountry("LU");
        locationCountryOnly.bLevel().setSignerLocation(countryOnly);
        emit("signer-location-country-only", locationCountryOnly);

        CAdESSignatureParameters locationAddressOnly = base(DigestAlgorithm.SHA256, null);
        SignerLocation addressOnly = new SignerLocation();
        addressOnly.setPostalAddress(Collections.singletonList("Only a postal address"));
        locationAddressOnly.bLevel().setSignerLocation(addressOnly);
        emit("signer-location-address-only", locationAddressOnly);

        // ---------------------------------------------------------------- mime type
        emitWithDocument("mime-type-binary", base(DigestAlgorithm.SHA256, null),
                new InMemoryDocument("content".getBytes(StandardCharsets.UTF_8), "content.bin"));
        DSSDocument pdf = new InMemoryDocument("content".getBytes(StandardCharsets.UTF_8), "content.pdf");
        pdf.setMimeType(MimeTypeEnum.PDF);
        emitWithDocument("mime-type-pdf", base(DigestAlgorithm.SHA256, null), pdf);

        // ---------------------------------------------------------------- content timestamp
        CAdESSignatureParameters contentTimestamp = base(DigestAlgorithm.SHA256, null);
        contentTimestamp.setContentTimestamps(Collections.singletonList(new TimestampToken(
                Files.readAllBytes(testdata.resolve("content-timestamp.tst")), TimestampType.CONTENT_TIMESTAMP)));
        emit("content-timestamp", contentTimestamp);

        // ---------------------------------------------------------------- everything at once
        CAdESSignatureParameters all = base(DigestAlgorithm.SHA512, date(2021, 1, 15, 10, 30, 45));
        all.bLevel().setClaimedSignerRoles(Collections.singletonList("Manager"));
        all.bLevel().setSignaturePolicy(policy(true, true, true));
        all.bLevel().setCommitmentTypeIndications(Collections.singletonList(CommitmentTypeEnum.ProofOfOrigin));
        all.bLevel().setSignerLocation(signerLocation);
        all.setContentIdentifierPrefix("DSS-");
        all.setContentIdentifierSuffix("20210115103045Z-4242");
        all.setContentTimestamps(Collections.singletonList(new TimestampToken(
                Files.readAllBytes(testdata.resolve("content-timestamp.tst")), TimestampType.CONTENT_TIMESTAMP)));
        emitWithDocument("everything", all, pdf);

        // content-hints suppresses the mime-type attribute
        CAdESSignatureParameters hintsAndMime = base(DigestAlgorithm.SHA256, null);
        hintsAndMime.setContentHintsType("1.2.840.113549.1.7.1");
        hintsAndMime.setContentHintsDescription("text/plain");
        emitWithDocument("content-hints-suppress-mime-type", hintsAndMime, pdf);

        Files.write(testdata.resolve("baseline-b-attributes.txt"), out.toString().getBytes(StandardCharsets.UTF_8));
        System.out.println("written " + testdata.resolve("baseline-b-attributes.txt"));
    }

    // ------------------------------------------------------------------------------ helpers

    static CAdESSignatureParameters empty() {
        CAdESSignatureParameters parameters = new CAdESSignatureParameters();
        parameters.setSignatureLevel(SignatureLevel.CAdES_BASELINE_B);
        parameters.setSignaturePackaging(SignaturePackaging.ENVELOPING);
        // BLevelParameters defaults the signing date to "now"; it cannot be unset (the setter
        // rejects null), so every case fixes it to DEFAULT_SIGNING_DATE for reproducibility.
        parameters.bLevel().setSigningDate(DEFAULT_SIGNING_DATE);
        return parameters;
    }

    static final Date DEFAULT_SIGNING_DATE = date(2021, 1, 15, 10, 30, 45);

    static CAdESSignatureParameters base(DigestAlgorithm digestAlgorithm, Date signingDate) {
        CAdESSignatureParameters parameters = empty();
        parameters.setDigestAlgorithm(digestAlgorithm);
        parameters.setSigningCertificate(signer);
        if (signingDate != null) {
            parameters.bLevel().setSigningDate(signingDate);
        }
        return parameters;
    }

    static Policy policy(boolean spuri, boolean userNotice, boolean docSpecification) {
        Policy policy = new Policy();
        policy.setId("1.2.3.4.5.6");
        policy.setDigestAlgorithm(DigestAlgorithm.SHA256);
        policy.setDigestValue(digestValue());
        if (spuri) {
            policy.setSpuri("http://policy.example.org/policy.der");
        }
        if (userNotice) {
            UserNotice notice = new UserNotice();
            notice.setOrganization("DSS Go Port");
            notice.setNoticeNumbers(1, 2);
            notice.setExplicitText("A user notice");
            policy.setUserNotice(notice);
        }
        if (docSpecification) {
            SpDocSpecification spDocSpecification = new SpDocSpecification();
            spDocSpecification.setId("1.2.3.4.5.7");
            spDocSpecification.setQualifier(ObjectIdentifierQualifier.OID_AS_URN);
            policy.setSpDocSpecification(spDocSpecification);
        }
        return policy;
    }

    /** A fixed 32-byte "digest": 0x00 .. 0x1F. */
    static byte[] digestValue() {
        byte[] value = new byte[32];
        for (int i = 0; i < value.length; i++) {
            value[i] = (byte) i;
        }
        return value;
    }

    static Date date(int year, int month, int day, int hour, int minute, int second) {
        Calendar calendar = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
        calendar.clear();
        calendar.set(year, month - 1, day, hour, minute, second);
        return calendar.getTime();
    }

    static CertificateToken loadCertificate(Path path) throws Exception {
        CertificateFactory factory = CertificateFactory.getInstance("X.509");
        try (ByteArrayInputStream is = new ByteArrayInputStream(Files.readAllBytes(path))) {
            return new CertificateToken((X509Certificate) factory.generateCertificate(is));
        }
    }

    static void emit(String name, CAdESSignatureParameters parameters) throws Exception {
        emitWithDocument(name, parameters, null);
    }

    static void emitWithDocument(String name, CAdESSignatureParameters parameters, DSSDocument documentToSign)
            throws Exception {
        CAdESLevelBaselineB profile = new CAdESLevelBaselineB(documentToSign);
        AttributeTable table = profile.getSignedAttributes(parameters);

        ASN1EncodableVector vector = table.toASN1EncodableVector();
        List<Attribute> attributes = new ArrayList<>(vector.size());
        for (int i = 0; i < vector.size(); i++) {
            attributes.add(Attribute.getInstance(vector.get(i)));
        }
        // The AttributeTable is a Hashtable, so its enumeration order is not defined; the DER
        // encoding of each attribute is, and the SET OF below sorts them. Emit them sorted by
        // their own encoding, so the file is stable across runs.
        List<byte[]> encodings = new ArrayList<>(attributes.size());
        for (Attribute attribute : attributes) {
            encodings.add(attribute.getEncoded("DER"));
        }
        encodings.sort(BaselineBFixtures::compare);

        out.append("case ").append(name).append('\n');
        for (byte[] encoding : encodings) {
            out.append("attr ").append(hex(encoding)).append('\n');
        }
        out.append("set ").append(hex(new DERSet(vector).getEncoded("DER"))).append('\n');
    }

    static int compare(byte[] a, byte[] b) {
        int length = Math.min(a.length, b.length);
        for (int i = 0; i < length; i++) {
            int diff = (a[i] & 0xff) - (b[i] & 0xff);
            if (diff != 0) {
                return diff;
            }
        }
        return a.length - b.length;
    }

    static String hex(byte[] data) {
        StringBuilder sb = new StringBuilder(data.length * 2);
        for (byte b : data) {
            sb.append(Character.forDigit((b >> 4) & 0xf, 16)).append(Character.forDigit(b & 0xf, 16));
        }
        return sb.toString();
    }

    @SuppressWarnings("unused")
    static ASN1Encodable unused() {
        return null;
    }
}
